/**
 * Microsoft Outlook Node - Version 2
 * Discriminator: resource=draft, operation=update
 */


interface Credentials {
  microsoftOutlookOAuth2Api: CredentialReference;
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Update a calendar */
export type MicrosoftOutlookV2DraftUpdateParams = {
  resource: 'draft';
  operation: 'update';
  authentication?: 'microsoftOutlookOAuth2Api' | 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * The mailbox the Service Principal should act on. In the action node this is evaluated per input item (an expression can target a different mailbox per item); the trigger resolves it once.
 * @displayOptions.show { authentication: ["microsoftEntraServicePrincipalApi"] }
 * @default {"mode":"id","value":""}
 */
    mailbox?: { __rl: true; mode: 'id'; value: string; cachedResultName?: string };
/**
 * Draft
 * @searchListMethod searchDrafts
 * @default {"mode":"list","value":""}
 */
    draftId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Update Fields
 * @default {}
 */
    updateFields?: {
    /** Comma-separated list of email addresses of BCC recipients
     */
    bccRecipients?: string | Expression<string>;
    /** Choose from the list, or specify IDs using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
     * @loadOptionsMethod getCategoriesNames
     * @default []
     */
    categories?: string[];
    /** Comma-separated list of email addresses of CC recipients
     */
    ccRecipients?: string | Expression<string>;
    /** Custom Headers
     * @default {}
     */
    internetMessageHeaders?: {
        /** Header
     */
    headers?: Array<{
      /** Name of the header
       */
      name?: string | Expression<string>;
      /** Value to set for the header
       */
      value?: string | Expression<string>;
    }>;
  };
    /** The owner of the mailbox from which the message is sent. Must correspond to the actual mailbox used.
     */
    from?: string | Expression<string>;
    /** The importance of the message
     * @default Normal
     */
    importance?: 'Low' | 'Normal' | 'High' | Expression<string>;
    /** Whether the message must be marked as read
     * @default false
     */
    isRead?: boolean | Expression<boolean>;
    /** Message body content
     */
    bodyContent?: string | Expression<string>;
    /** Message body content type
     * @default html
     */
    bodyContentType?: 'html' | 'Text' | Expression<string>;
    /** Whether a read receipt is requested for the message
     * @default false
     */
    isReadReceiptRequested?: boolean | Expression<boolean>;
    /** Email address to use when replying
     */
    replyTo?: string | Expression<string>;
    /** The subject of the message
     */
    subject?: string | Expression<string>;
    /** Comma-separated list of email addresses of recipients
     */
    toRecipients?: string | Expression<string>;
  };
};

